using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
        // Restore old property name for existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 uses only the raw key for "id" (e.g. "1").
        // Previously it was "EntityType|KeyValue" (e.g. "Blog|1").
        // Restore old id format for existing documents.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // Breaking change 3: EF Core 9 no longer supports HasIndex on Cosmos.
        // Indexes are managed by Cosmos DB indexing policy, not EF.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // For raw SQL queries: use "$type" or configure discriminator (done above).
    // Old query: SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // Still works because we explicitly set discriminator property name above.
}

// Custom ID value generator to preserve legacy "Type|Key" format
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{entry.Property("Id").CurrentValue}";
}

