{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF Core 9 Cosmos uses patch-based updates by default
        // (only changed properties are sent). If full-document replace semantics
        // are needed, opt in per-save:
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
        // Patch API is generally fine here; no code change needed unless you
        // rely on full-document replace for concurrency/triggers.
    }
}

